function catRows(cats, planKey) {
    return cats.map((c) => {
        const v = c.vals[planKey];
        const valStr = typeof v === "string" ? v : baht(v) + (c.unit ? " " + c.unit : "");
        const sharedNote = (c.sharedPlans && c.sharedPlans.includes(planKey)) ? ` — แผนนี้ใช้วงเงินก้อนเดียวกันร่วมกับหมวดที่ ${c.sharedWithNo} (ไม่ได้แยกกัน)` : "";
        return [`หมวดที่ ${c.no} — ${c.desc}${sharedNote}`, valStr];
    });
}
