function rpprRange(si) {
    if (si < 50000)
        return null;
    if (si < 100000)
        return [300, 500];
    if (si < 500000)
        return [300, 2000];
    if (si < 750000)
        return [300, 2500];
    if (si < 1000000)
        return [300, 3000];
    if (si < 3000000)
        return [300, 4000];
    return [300, 5000];
}
