    // จำนวนปีที่ต้องชำระเบี้ยของแบบทุนประกันหลักแต่ละตัว (ใช้คำนวณเบี้ยรวมตลอดโครงการ)
    function mainPolicyPaymentYears(id) {
        if (id === "SUD")
            return 20;
        if (id === "LIFE99")
            return Math.max(1, 99 - age);
        if (id === "UNJAI")
            return Math.max(1, 90 - age);
        if (id === "CANCERMAX")
            return Math.max(1, 90 - age);
        if (id === "PLUS2")
            return plus2Term || 0;
        if (id === "PRESTIGE")
            return prestigeTerm || 0;
        if (id === "HAPPYPENSION")
            return happypensionTerm ? happypensionRow(happypensionTerm).premiumYears : 0;
        if (id === "HAPPYSAVING")
            return happysavingTerm || 0;
        if (id === "HAPPYWL")
            return happywlTerm || 0;
        if (id === "HRP9920")
            return 20;
        if (id === "HRPDIV")
            return hrpdivTerm || 0;
        if (id === "HRP9901")
            return 1;
        if (id === "HAPPYWL9901")
            return 1;
        if (id === "HAPPYKID")
            return 20;
        return 0;
    }
    useEffect(() => {
        if (csDisabled && selected.CS)
            setSelected((s) => (Object.assign(Object.assign({}, s), { CS: false })));
    }, [csDisabled]);
