    function calcCHAK() {
        if (age < CHAK_MIN_AGE || age > CHAK_MAX_AGE)
            return { ok: false, msg: `อายุรับประกัน ${CHAK_MIN_AGE}-${CHAK_MAX_AGE} ปี` };
        if (occClass === 3)
            return { ok: false, msg: "เฉพาะกาล (ฉก.) รับประกันเฉพาะชั้นอาชีพ 1-2 เท่านั้น (ไม่รับชั้นอาชีพ 3)" };
        if (!chakTerm)
            return { ok: false, msg: "กรุณาเลือกระยะเวลาความคุ้มครอง (5 / 10 / 15 / 18 ปี)" };
        if (chakSI < CHAK_MIN_SI)
            return { ok: false, msg: `ทุนประกันขั้นต่ำ ${baht(CHAK_MIN_SI)} บาท` };
        const ti = CHAK_TERMS.indexOf(chakTerm);
        const idx = age - CHAK_MIN_AGE;
        const rate = (gender === "female" ? CHAK_FEMALE : CHAK_MALE)[idx][ti] * (1 - chakDiscount(chakSI));
        const premium = (rate * chakSI) / 1000;
        return { ok: true, premium, benefits: [
                ["ระยะเวลาความคุ้มครอง/ชำระเบี้ย", chakTerm + " ปี (ต้องไม่เกินระยะเวลาของกรมธรรม์หลัก)"],
                ["ทุนประกันภัย", baht(chakSI)],
                ["เสียชีวิต", baht(chakSI) + " (100% ของทุนประกันภัย)"],
            ] };
    }
    function calcCHAP() {
        if (age < 0 || age > 14)
            return { ok: false, msg: "เฉพาะกาลผู้ปกครอง (ฉป.) สำหรับผู้เยาว์อายุ 0-14 ปีเท่านั้น" };
        if (!chapTerm)
            return { ok: false, msg: "กรุณาเลือกระยะเวลาความคุ้มครอง (5 / 10 / 15 / 18 ปี)" };
        if (chapPayorAge < 20 || chapPayorAge > 60)
            return { ok: false, msg: "อายุผู้ปกครองต้อง 20-60 ปี" };
        if (chapPayorAge + chapTerm > 65)
            return { ok: false, msg: "อายุผู้ปกครองรวมกับระยะเวลาเอาประกันภัยต้องไม่เกิน 65 ปี" };
        if (chapSI < CHAK_MIN_SI)
            return { ok: false, msg: `ทุนประกันขั้นต่ำ ${baht(CHAK_MIN_SI)} บาท` };
        const ti = CHAK_TERMS.indexOf(chapTerm);
        const idx = chapPayorAge - CHAK_MIN_AGE;
        if (idx < 0 || idx >= (chapPayorGender === "female" ? CHAK_FEMALE : CHAK_MALE).length)
            return { ok: false, msg: "อายุผู้ปกครองไม่เข้าตารางเบี้ย" };
        const rate = (chapPayorGender === "female" ? CHAK_FEMALE : CHAK_MALE)[idx][ti] * (1 - chakDiscount(chapSI));
        const premium = (rate * chapSI) / 1000;
        return { ok: true, premium, benefits: [
                ["เพศ/อายุผู้ปกครอง (ใช้คำนวณเบี้ย)", (chapPayorGender === "female" ? "หญิง" : "ชาย") + " " + chapPayorAge + " ปี"],
                ["ระยะเวลาความคุ้มครอง/ชำระเบี้ย", chapTerm + " ปี"],
                ["ทุนประกันภัย", baht(chapSI)],
                ["หากผู้ปกครองเสียชีวิตในระยะเวลาเอาประกันภัย", baht(chapSI) + " จ่ายให้แก่ผู้เอาประกันภัย (ผู้เยาว์) โดยตรง"],
            ] };
    }
    function calcPH() {
        if (age < PH_MIN_AGE || age > PH_MAX_AGE)
            return { ok: false, msg: `อายุรับประกัน ${PH_MIN_AGE}-${PH_MAX_AGE} ปี (ต่ออายุได้ถึงอายุ 98 ปี)` };
        if (mainSI < PH_MIN_MAIN_SI)
            return { ok: false, msg: `ต้องมีทุนประกันชีวิตหลักขั้นต่ำ ${baht(PH_MIN_MAIN_SI)} บาท จึงจะซื้อ เพรสทีจ เฮลธ์ ปลดล็อค ได้` };
        if (!phPlan)
            return { ok: false, msg: "กรุณาเลือกแผนความคุ้มครอง (20 / 30 / 50 / 100 / 200 ล้านบาท)" };
        if (phDeduct === null)
            return { ok: false, msg: "กรุณาเลือกความรับผิดส่วนแรก (Deductible)" };
        const canPickArea = phPlan === 100000000 || phPlan === 200000000;
        const area = canPickArea ? phArea : "thailand";
        let rate;
        if (area === "thailand") {
            const pi = PH_PLANS.indexOf(phPlan);
            const di = PH_DEDUCT[phPlan].indexOf(phDeduct);
            const col = pi * 2 + di;
            const table = occClass === 3 ? PH_RATE_OCC3 : PH_RATE_OCC12;
            rate = table[age - PH_MIN_AGE][col];
        }
        else {
            // ตารางพื้นที่กว้างกว่าไทย ใช้ได้เฉพาะแผน 100/200 ล้าน และไม่มีตัวเลือก Deductible (ความรับผิดส่วนแรก = 0 เท่านั้น)
            if (phDeduct !== 0)
                return { ok: false, msg: "พื้นที่คุ้มครองนอกประเทศไทย ไม่มีตัวเลือกความรับผิดส่วนแรก กรุณาเลือก \"ไม่มี\"" };
            const areaColBase = { asia: 0, world_ex_us: 2, world: 4 }[area];
            const planCol = phPlan === 100000000 ? 0 : 1;
            const col = areaColBase + planCol;
            const table = occClass === 3 ? PH_RATE_AREA_OCC3 : PH_RATE_AREA_OCC12;
            rate = table[age - PH_MIN_AGE][col];
        }
        const premium = rate; // ตารางนี้เป็นเบี้ยรายปีสำเร็จรูปต่อกรมธรรม์ ไม่ใช่อัตราต่อ 1,000 บาท
        const pi = PH_PLANS.indexOf(phPlan);
        const roomLimit = [8000, 10000, 12000, 15000, 25000][pi];
        const item4 = [50000, 100000, 200000, 300000, 400000][pi];
        const item9a = pi === 2 ? 50000 : pi === 3 ? 100000 : pi === 4 ? "จ่ายตามจริง" : null;
        const item9b = pi === 2 ? 5000 : pi === 3 ? 10000 : pi === 4 ? 50000 : null;
        const item10a = pi === 3 ? 15000 : pi === 4 ? 50000 : null;
        const item10b = pi === 3 ? 10000 : pi === 4 ? 40000 : null;
        return { ok: true, premium, benefits: [
                ["แผนความคุ้มครอง", baht(phPlan) + " ต่อรอบปีกรมธรรม์"],
                ["พื้นที่ความคุ้มครอง", PH_AREAS.find((a) => a.key === area).label],
                ["ความรับผิดส่วนแรก (Deductible)", phDeduct === 0 ? "ไม่มี" : baht(phDeduct) + " ต่อการเข้ารักษาตัวครั้งใดครั้งหนึ่ง"],
                ["หมวดที่ 1: ค่าห้อง/ค่าอาหาร/ค่าบริการพยาบาล (ผู้ป่วยใน) ต่อการเข้าพักรักษาตัวครั้งใดครั้งหนึ่ง", baht(roomLimit) + "/วัน หรือค่าห้องเดี่ยวราคาเริ่มต้นของโรงพยาบาลต่อวัน แล้วแต่จำนวนใดสูงกว่า (ใช้สำหรับโรงพยาบาลในประเทศไทยเท่านั้น) · กรณี ICU จ่ายตามจริง รวมหมวด 1 ทั้งหมดสูงสุดไม่เกิน 365 วัน"],
                ["หมวดที่ 2: ค่าตรวจวินิจฉัย/บำบัดรักษา/โลหิต/พยาบาล/ยา/เวชภัณฑ์ (ผู้ป่วยใน)", "จ่ายตามจริง (กายภาพบำบัด/กิจกรรมบำบัดในหมวดย่อย 2.2 สูงสุด 30 วันต่อโรค, ยากลับบ้านหมวดย่อย 2.4 สูงสุด 30 วัน)"],
                ["หมวดที่ 3: ค่าแพทย์ตรวจรักษา (ผู้ป่วยใน)", "จ่ายตามจริง สูงสุดไม่เกิน 365 วันต่อการเข้าพักรักษาตัวครั้งใดครั้งหนึ่ง"],
                ["หมวดที่ 4: ค่าผ่าตัด/หัตถการ (ห้องผ่าตัด, ยา, เวชภัณฑ์, แพทย์ผ่าตัด, วิสัญญีแพทย์)", "จ่ายตามจริง (ไม่รวมการผ่าตัดเปลี่ยนอวัยวะ)"],
                ["หมวดที่ 5: ผ่าตัดใหญ่ที่ไม่ต้องพักรักษาตัว (Day Surgery)", "จ่ายตามจริง"],
                ["หมวดที่ 6: ค่าตรวจก่อน/ค่ารักษาต่อเนื่องหลังผู้ป่วยใน (ภายใน 30 วันก่อน-หลัง)", "จ่ายตามจริง"],
                ["หมวดที่ 7: ค่ารักษาบาดเจ็บฉุกเฉิน ผู้ป่วยนอก (ภายใน 24 ชม. หลังอุบัติเหตุ)", "จ่ายตามจริง"],
                ["หมวดที่ 8: เวชศาสตร์ฟื้นฟู หลังออกจากผู้ป่วยใน (1 ครั้ง/วัน ภายใน 60 วัน)", "จ่ายตามจริง"],
                ["หมวดที่ 9: ล้างไตผ่านทางเส้นเลือด (ไตวายเรื้อรัง)", "จ่ายตามจริง"],
                ["หมวดที่ 10: รังสีรักษา/รังสีร่วมรักษา/เวชศาสตร์นิวเคลียร์รักษา (มะเร็ง)", "จ่ายตามจริง"],
                ["หมวดที่ 11: เคมีบำบัด/เภสัชรังสีวิทยา/Targeted Therapy (มะเร็ง)", "จ่ายตามจริง"],
                ["หมวดที่ 12: ค่าบริการรถพยาบาลฉุกเฉิน", "จ่ายตามจริง"],
                ["หมวดที่ 13: ค่ารักษาพยาบาลโดยการฉีดยาเข้าเล็บ", "จ่ายตามจริง"],
                ["ผลประโยชน์เพิ่มเติม 3: อวัยวะเทียม/อุปกรณ์ทดแทนการทำหน้าที่ (ในหมวดย่อย 2.2 และหมวด 8)", "จ่ายตามจริง"],
                ["ผลประโยชน์เพิ่มเติม 4: เครื่องพยุงกระดูก/กล้ามเนื้อ เครื่องมือแพทย์ควบคุม หรืออวัยวะเทียมภายนอก (ตลอดชีพของสัญญานี้)", baht(item4)],
                ["ผลประโยชน์เพิ่มเติม 5: ค่าพยาบาลส่วนตัวตามคำแนะนำแพทย์ หลังผู้ป่วยใน (สูงสุด 60 วัน/ปี)", "จ่ายตามจริง"],
                ["ผลประโยชน์เพิ่มเติม 6: ขยายคุ้มครองกรณีไม่ต้องนอนโรงพยาบาล (รักษาบาดเจ็บต่อเนื่อง 15 วัน / ทันตกรรมจากอุบัติเหตุ / กายภาพบำบัดขั้นสูง)", "จ่ายตามจริง"],
                ["ผลประโยชน์เพิ่มเติม 7: ปรึกษาแพทย์/ตรวจวินิจฉัยก่อนรักษามะเร็งด้วย Targeted Therapy", "จ่ายตามจริง"],
                ["ผลประโยชน์เพิ่มเติม 8: ชดเชยกรณีผู้ป่วยอาการวิกฤต (1 ครั้งตลอดชีพ ไม่รวมในวงเงินสูงสุดต่อปี)", baht(500000) + " (เท่ากันทุกแผน)"],
                ["ผลประโยชน์เพิ่มเติม 9: ค่าแพทย์เฉพาะทาง/ตรวจ Lab/ค่ายา (ผู้ป่วยนอก) ต่อปี", item9a === null ? "ไม่คุ้มครองในแผนนี้ (มีเฉพาะแผน 50 ล้านขึ้นไป)" : (item9a === "จ่ายตามจริง" ? item9a : baht(item9a))],
                ["ผลประโยชน์เพิ่มเติม 9: การแพทย์ทางเลือก (ผู้ป่วยนอก) ต่อปี", item9b === null ? "ไม่คุ้มครองในแผนนี้ (มีเฉพาะแผน 50 ล้านขึ้นไป)" : baht(item9b)],
                ["ผลประโยชน์เพิ่มเติม 10: ตรวจสุขภาพประจำปี/วัคซีน/จิตเวชผู้ป่วยนอก ต่อปี", item10a === null ? "ไม่คุ้มครองในแผนนี้ (มีเฉพาะแผน 100 ล้านขึ้นไป)" : baht(item10a)],
                ["ผลประโยชน์เพิ่มเติม 10: ตรวจรักษาทางทันตกรรม ต่อปี", item10b === null ? "ไม่คุ้มครองในแผนนี้ (มีเฉพาะแผน 100 ล้านขึ้นไป)" : baht(item10b)],
                ["ผลประโยชน์เพิ่มเติม 11: รักษาด้วยวิวัฒนาการทางการแพทย์ที่ราชวิทยาลัยไทยรับรอง", "จ่ายตามจริง (ครอบคลุมหมวด 1-13 และบันทึกสลักหลังอาการวิกฤต)"],
                ["ผลประโยชน์เพิ่มเติม 12: ชดเชยรายได้ผู้ป่วยในกรณีไม่เรียกร้องค่ารักษา (เฉพาะแผนไม่มี Deductible)", "2,000 บาท/วัน สูงสุด 10 วันต่อปี"],
                ["เงื่อนไข", "ต้องแนบกับสัญญาประกันชีวิตทุนขั้นต่ำ 50,000 บาท · ต่ออายุปีต่อปีจนถึงอายุ 98 ปี"],
            ] };
    }
    // สร้างตารางอัตราเบี้ยที่จะปรับในอนาคต (รายปีหรือรายช่วงอายุ) ของแบบที่ไม่ใช่เบี้ยคงที่ ตามแผน/ทุนประกันที่เลือกไว้ปัจจุบัน ไปจนถึงอายุสูงสุดที่ต่ออายุได้
    function buildPremiumSchedule(id) {
        const rows = [];
        switch (id) {
            case "TPD": {
                if (tpdSI <= 0)
                    break;
                const table = gender === "female" ? TPD_FEMALE : TPD_MALE;
                for (let idx = Math.max(0, age - TPD_MIN_AGE); idx < table.length; idx++) {
                    rows.push({ label: `อายุ ${TPD_MIN_AGE + idx} ปี`, premium: (table[idx] * tpdSI) / 1000 });
                }
                break;
            }
            case "SUPER": {
                if (supSI <= 0)
                    break;
                const table = gender === "female" ? SUPER_FEMALE : SUPER_MALE;
                for (let idx = Math.max(0, age - SUPER_MIN_AGE); idx < table.length; idx++) {
                    rows.push({ label: `อายุ ${SUPER_MIN_AGE + idx} ปี`, premium: (table[idx] * supSI) / 1000 });
                }
                break;
            }
            case "HAPPYCI": {
                const ti = HAPPYCI_TERMS.indexOf(happyciTerm);
                if (ti < 0 || happyciSI <= 0)
                    break;
                const table = gender === "female" ? HAPPYCI_FEMALE : HAPPYCI_MALE;
                for (let a = Math.max(age, 0); a < table.length; a++) {
                    rows.push({ label: `อายุ ${a} ปี`, premium: (table[a][ti] * happyciSI) / 1000 });
                }
                break;
            }
            case "LLC": {
                if (!llcVariant || llcSI <= 0)
                    break;
                const table = llcVariant === "99" ? (gender === "female" ? LLC99_FEMALE : LLC99_MALE) : (gender === "female" ? LLC10_FEMALE : LLC10_MALE);
                for (let idx = Math.max(0, age - LLC_MIN_AGE); idx < table.length; idx++) {
                    rows.push({ label: `อายุ ${LLC_MIN_AGE + idx} ปี`, premium: (table[idx] * llcSI) / 1000 });
                }
                break;
            }
            case "VH": {
                const pi = VH_PLANS.indexOf(vhPlan);
                const fromBi = bandIndex(age, VH_BANDS);
                if (pi < 0 || fromBi < 0)
                    break;
                const occGroup = occClass === 3 ? "c3" : "c12";
                for (let bi = fromBi; bi < VH_BANDS.length; bi++) {
                    const [lo, hi] = VH_BANDS[bi];
                    rows.push({ label: `อายุ ${lo}-${hi} ปี`, premium: VH_TABLE[gender][occGroup][bi][pi] });
                }
                break;
            }
            case "VHKIDS": {
                const pi = VHKIDS_PLANS.indexOf(vhkidsPlan);
                const fromBi = bandIndex(age, VHKIDS_BANDS);
                if (pi < 0 || fromBi < 0)
                    break;
                const table = gender === "female" ? VHKIDS_FEMALE : VHKIDS_MALE;
                for (let bi = fromBi; bi < VHKIDS_BANDS.length; bi++) {
                    const [lo, hi] = VHKIDS_BANDS[bi];
                    rows.push({ label: `อายุ ${lo}-${hi} ปี`, premium: table[bi][pi] });
                }
                break;
            }
            case "HHP": {
                const pi = HHP_PLANS.indexOf(hhpPlan);
                const di = HHP_DEDUCT.indexOf(hhpDeduct);
                const fromBi = bandIndex(age, HHP_BANDS);
                if (pi < 0 || di < 0 || fromBi < 0)
                    break;
                const occGroup = occClass === 3 ? "c3" : "c12";
                const table = HHP_TABLE[gender][occGroup];
                for (let bi = fromBi; bi < HHP_BANDS.length; bi++) {
                    const [lo, hi] = HHP_BANDS[bi];
                    rows.push({ label: `อายุ ${lo}-${hi} ปี`, premium: table[bi][pi][di] });
                }
                break;
            }
            case "RPPR": {
                const range = rpprRange(mainSI);
                const fromBi = bandIndex(age, RPPR_BANDS);
                if (!range || fromBi < 0 || rpprDaily <= 0)
                    break;
                const table = gender === "female" ? RPPR_FEMALE : RPPR_MALE;
                for (let bi = fromBi; bi < RPPR_BANDS.length; bi++) {
                    const [lo, hi] = RPPR_BANDS[bi];
                    rows.push({ label: `อายุ ${lo}-${hi} ปี`, premium: (table[bi] * rpprDaily) / 100 });
                }
                break;
            }
            case "ACC": {
                const pi = ACC_PLANS.indexOf(accPlan);
                const fromBi = bandIndex(age, ACC_BANDS);
                if (pi < 0 || fromBi < 0)
                    break;
                for (let bi = fromBi; bi < ACC_BANDS.length; bi++) {
                    const [lo, hi] = ACC_BANDS[bi];
                    rows.push({ label: `อายุ ${lo}-${hi} ปี`, premium: ACC_RATES[occClass][bi][pi] });
                }
                break;
            }
            case "OPD": {
                const pi = OPD_PLANS.indexOf(opdPlan);
                const fromBi = bandIndex(age, OPD_BANDS);
                if (pi < 0 || fromBi < 0)
                    break;
                for (let bi = fromBi; bi < OPD_BANDS.length; bi++) {
                    const [lo, hi] = OPD_BANDS[bi];
                    rows.push({ label: `อายุ ${lo}-${hi} ปี`, premium: OPD_RATES[bi][pi] });
                }
                break;
            }
            case "SS": {
                if (ssSI <= 0)
                    break;
                const fromBi = bandIndex(age, SS_BANDS);
                if (fromBi < 0)
                    break;
                const table = gender === "female" ? SS_FEMALE : SS_MALE;
                for (let bi = fromBi; bi < SS_BANDS.length; bi++) {
                    const [lo, hi] = SS_BANDS[bi];
                    rows.push({ label: `อายุ ${lo}-${hi} ปี`, premium: (table[bi] * ssSI) / 1000 });
                }
                break;
            }
            case "PH": {
                if (!phPlan || phDeduct === null)
                    break;
                const canPickArea = phPlan === 100000000 || phPlan === 200000000;
                const area = canPickArea ? phArea : "thailand";
                for (let a = Math.max(age, PH_MIN_AGE); a <= PH_MAX_AGE + 18; a++) { // ต่ออายุได้ถึง 98 ปี (98-80=18 ปีเกินอายุรับประกันสูงสุด)
                    const idx = a - PH_MIN_AGE;
                    let rate;
                    if (area === "thailand") {
                        const pi = PH_PLANS.indexOf(phPlan);
                        const di = PH_DEDUCT[phPlan].indexOf(phDeduct);
                        const col = pi * 2 + di;
                        const table = occClass === 3 ? PH_RATE_OCC3 : PH_RATE_OCC12;
                        if (idx >= table.length)
                            break;
                        rate = table[idx][col];
                    }
                    else {
                        if (phDeduct !== 0)
                            break;
                        const areaColBase = { asia: 0, world_ex_us: 2, world: 4 }[area];
                        const planCol = phPlan === 100000000 ? 0 : 1;
                        const table = occClass === 3 ? PH_RATE_AREA_OCC3 : PH_RATE_AREA_OCC12;
                        if (idx >= table.length)
                            break;
                        rate = table[idx][areaColBase + planCol];
                    }
                    rows.push({ label: `อายุ ${a} ปี`, premium: rate });
                }
                break;
            }
            default: break;
        }
        return rows;
    }
